/**
 * LYZDownload 推广页入口
 * 复用共享组件渲染：Navbar / Hero / Features（亮点·能力·管理）/ DownloadCTA / Footer
 * 「立即下载」按钮按访客系统自动指向对应平台的安装包（见 platform.js）
 */
import '../../styles/global.css';
import './style.css';
import {
  Navbar,
  Hero,
  Features,
  DownloadCTA,
  Footer,
  BRAND,
  NAV_LINKS,
  FOOTER_LINKS,
  COPYRIGHT,
  scrollToHash,
} from '../../components';
import { pickDownloadUrl, platformLabel, platformIcon } from '../../components/platform';

// ─── 桌面端下载入口（换地址只改这里）───
const VERSION = '0.4.3';

// 注意：0.4.2 及更早的 tag 带 v 前缀（v0.4.2），0.4.3 起改为不带 v
const PLATFORM_URLS = {
  windows:
    'https://github.com/zhenzi0322-microsoft/LYZDownload/releases/download/0.4.3/LYZDownload_0.4.3_x64-setup.exe',
  linux:
    'https://github.com/zhenzi0322-microsoft/LYZDownload/releases/download/0.4.3/LYZDownload_0.4.3_amd64.AppImage',
  macosAppleSilicon:
    'https://github.com/zhenzi0322-microsoft/LYZDownload/releases/download/0.4.3/LYZDownload_0.4.3_aarch64.dmg',
  macosIntel:
    'https://github.com/zhenzi0322-microsoft/LYZDownload/releases/download/0.4.3/LYZDownload_0.4.3_x64.dmg',
};

// 发布页 / Hero 次按钮与「全部版本」入口
const RELEASE_URL =
  'https://github.com/zhenzi0322-microsoft/LYZDownload/releases/tag/0.4.3';

// 浏览器扩展 · Microsoft Edge / Chrome / Firefox 扩展商店
const EXTENSION_URL =
  'https://microsoftedge.microsoft.com/addons/detail/lyzdownload/mhchfbkbfnangkclddikklbcoojkfjbj';

const CHROME_EXTENSION_URL =
  'https://chromewebstore.google.com/detail/lyzdownload/lhkgpbgbhiecpojnlkfckmdkdcgelieg';

const FIREFOX_EXTENSION_URL =
  'https://addons.mozilla.org/zh-CN/firefox/addon/lyzdownload';

// ─── 按访客系统自动选包 ──
// 识别不出系统时回退到 Windows（绝大多数桌面访客是 Windows，命中率最高）
const AUTO_DOWNLOAD_URL = pickDownloadUrl(PLATFORM_URLS);
// 按钮上显示访客的平台名，让「为什么下的是这个」一目了然
const AUTO_PLATFORM_LABEL = platformLabel();
const AUTO_PLATFORM_ICON = platformIcon();

const APP_CONFIG = {
  name: 'LYZDownload',
  tagline: '轻量级全能桌面下载器',
  description:
    '同时搞定 HTTP、磁力 / BT、M3U8 流媒体三类下载——体积小、开箱即用，设置简单、下载更稳更快。',
  downloadUrl: AUTO_DOWNLOAD_URL,
  version: VERSION,
};

// ─── 核心亮点 ───
const HIGHLIGHTS = [
  { icon: '🔀', title: '三大协议合一', description: 'HTTP 文件、磁力 / BT、M3U8 流媒体，一个软件全包，不必再装多个下载工具。' },
  { icon: '🧩', title: '浏览器扩展', description: 'Edge / Chrome / Firefox 三家商店均已上架，浏览网页时一键唤起下载，桌面端与扩展随时协同。' },
  { icon: '⚡', title: '安装包不到 10 MB', description: 'Windows 安装包仅 6 MB、macOS 约 10 MB，下载安装都是几秒的事，卸载也不留残留。' },
  { icon: '🌐', title: '代理一键配置', description: '设置一次全局生效，新下载任务自动套用，无需逐个配置。' },
  { icon: '🪟', title: '清爽桌面体验', description: '自绘标题栏、禁用浏览器右键、系统托盘常驻，更像原生应用。' },
  { icon: '📊', title: '实时进度掌控', description: '进度、速度、剩余时间一目了然，暂停 / 继续 / 取消随心切换。' },
];

// ─── 三大下载能力 ───
const CAPABILITIES = [
  { icon: '⬇️', title: 'HTTP / HTTPS', description: 'Range 分片 + 多线程并发自动加速大文件，支持断点续传与暂停 / 继续 / 取消。' },
  { icon: '🧲', title: '磁力 / BitTorrent', description: '内嵌 librqbit 引擎，DHT + 多 Tracker 协同并自动补充 HTTP(S) Tracker 兜底，超时看门狗防卡死，完成后自动做种。' },
  { icon: '📺', title: 'M3U8 / HLS', description: '并发拉取 .ts 分片 → AES-128 解密 → 自动合并输出，识别直播流并对异常分片超时熔断。' },
];

// ─── 任务管理 ───
const MANAGE = [
  { icon: '🗂️', title: '卡片式任务列表', description: '等待 / 下载中 / 已完成 / 失败 / 暂停，状态一目了然。' },
  { icon: '🔎', title: '搜索 · 筛选 · 排序', description: '每页 10 条分页，关键词搜索、分类筛选与排序齐备。' },
  { icon: '🏷️', title: '自定义分类', description: '模型 / 视频 / 其他，按用途自由归类管理。' },
  { icon: '✅', title: '批量多选', description: '支持多选与跨页批量选择，批量操作更高效。' },
  { icon: '📋', title: '剪贴板监控', description: '复制到磁力链接或下载地址自动识别，不用手动粘贴。' },
  { icon: '🔔', title: '系统通知', description: '任务完成或失败时弹系统通知，离开电脑也不会错过。' },
];

// ─── 平台下载按钮 ───
const PLATFORMS = [
  { name: 'Windows', url: PLATFORM_URLS.windows, icon: '🪟', sub: 'x64 · setup.exe' },
  { name: 'macOS Apple', url: PLATFORM_URLS.macosAppleSilicon, icon: '🍎', sub: 'M1+ · dmg' },
  { name: 'macOS Intel', url: PLATFORM_URLS.macosIntel, icon: '🖥️', sub: 'x64 · dmg' },
  { name: 'Linux', url: PLATFORM_URLS.linux, icon: '🐧', sub: 'amd64 · AppImage' },
];

// ─── 浏览器扩展安装入口 ───
const EXTENSIONS = [
  { name: 'Microsoft Edge', url: EXTENSION_URL, icon: '🧩', sub: '添加到扩展' },
  { name: 'Chrome', url: CHROME_EXTENSION_URL, icon: '🧭', sub: '添加到扩展' },
  { name: 'Firefox', url: FIREFOX_EXTENSION_URL, icon: '🦊', sub: '添加到扩展' },
];

// ─── Hero 右侧的模拟下载面板（纯 CSS，无外部图片依赖）───
function buildHeroVisual() {
  const panel = document.createElement('div');
  panel.className = 'dl-panel';
  panel.innerHTML = `
    <div class="dl-panel__bar">
      <span class="dl-dot"></span><span class="dl-dot"></span><span class="dl-dot"></span>
    </div>
    <div class="dl-panel__row">
      <span class="dl-tag dl-tag--http">HTTP</span>
      <div class="dl-track"><div class="dl-fill" style="width:72%"></div></div>
      <span class="dl-pct">72%</span>
    </div>
    <div class="dl-panel__row">
      <span class="dl-tag dl-tag--bt">磁力</span>
      <div class="dl-track"><div class="dl-fill" style="width:45%"></div></div>
      <span class="dl-pct">45%</span>
    </div>
    <div class="dl-panel__row">
      <span class="dl-tag dl-tag--m3u8">M3U8</span>
      <div class="dl-track"><div class="dl-fill" style="width:88%"></div></div>
      <span class="dl-pct">88%</span>
    </div>
  `;
  return panel;
}

// ─── 渲染页面 ───
function renderPage() {
  const root = document.getElementById('app');
  if (!root) return;

  // Navbar
  const navbar = new Navbar({
    brand: BRAND,
    links: NAV_LINKS,
    activeKey: 'lyzdownload',
  });
  root.appendChild(navbar.render());

  // Hero
  const hero = new Hero({
    title: APP_CONFIG.tagline,
    subtitle: APP_CONFIG.description,
    ctaText: `立即下载 v${VERSION} · ${AUTO_PLATFORM_LABEL}`,
    ctaIcon: AUTO_PLATFORM_ICON,
    ctaLink: APP_CONFIG.downloadUrl,
    secondaryText: '全部版本',
    secondaryIcon: '📋',
    secondaryLink: RELEASE_URL,
  });
  const heroEl = hero.render();
  const visual = heroEl.querySelector('.hero__visual');
  if (visual) visual.appendChild(buildHeroVisual());
  root.appendChild(heroEl);

  // 核心亮点
  const highlights = new Features({ title: '核心亮点', items: HIGHLIGHTS });
  const highlightsEl = highlights.render();
  highlightsEl.id = 'features';
  root.appendChild(highlightsEl);

  // 三大下载协议
  const caps = new Features({ title: '三大下载协议，一个全包', items: CAPABILITIES });
  const capsEl = caps.render();
  capsEl.id = 'capabilities';
  root.appendChild(capsEl);

  // 任务管理
  const manage = new Features({ title: '清爽高效的任务管理', items: MANAGE });
  const manageEl = manage.render();
  manageEl.id = 'manage';
  root.appendChild(manageEl);

  // 浏览器扩展安装
  const extension = new DownloadCTA({
    title: '安装浏览器扩展',
    subtitle: 'Edge / Chrome / Firefox 三家商店均已上架，浏览网页时随手唤起下载',
    platforms: EXTENSIONS,
    className: 'download-cta--extension',
  });
  const extensionEl = extension.render();
  extensionEl.id = 'extension';
  root.appendChild(extensionEl);

  // Download CTA
  const download = new DownloadCTA({
    title: `立即下载 LYZDownload v${VERSION}`,
    subtitle: '轻量原生 · 开箱即用，一个软件搞定三类下载',
    platforms: PLATFORMS,
  });
  const downloadEl = download.render();
  downloadEl.id = 'download';

  // 全部版本 / 历史发布入口
  const releaseNote = document.createElement('p');
  releaseNote.className = 'release-note';
  releaseNote.innerHTML = `需要旧版本或其他平台的安装包？前往
    <a href="${RELEASE_URL}" target="_blank" rel="noopener noreferrer">全部发布版本</a>`;
  downloadEl.querySelector('.container').appendChild(releaseNote);
  root.appendChild(downloadEl);

  // Footer
  const footer = new Footer({
    copyright: COPYRIGHT,
    links: FOOTER_LINKS,
  });
  root.appendChild(footer.render());

  // 正文进入 DOM 后补一次锚点定位
  scrollToHash();
}

// DOM Ready
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', renderPage);
} else {
  renderPage();
}
